import{_ as t,o as r,c as s,a2 as e}from"./chunks/framework.B2QVIpOM.js";const u=JSON.parse('{"title":"启思中学 · 年份未注明 · 中一 · 考试与面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"creative-secondary","school_zh":"启思中学","school_en":"Creative Secondary School","grade":"s1","year":"unknown","year_label":"年份未注明","type":"mixed","title":"启思中学 · 年份未注明 · 中一 · 考试与面试","anonymous":true,"source_ids":["CSS-S1-JAN-INTERACTIVE","CSS-S1-JUNE-INTERACTIVE","CSS-S1-MAY-WAITING","CSS002"],"rounds":["unknown"]},"headers":[],"relativePath":"reports/creative-secondary/s1/unknown-mixed.md","filePath":"reports/creative-secondary/s1/unknown-mixed.md"}'),n={name:"reports/creative-secondary/s1/unknown-mixed.md"};function p(a,o,c,g,l,i){return r(),s("div",null,[...o[0]||(o[0]=[e('<h1 id="启思中学-·-年份未注明-·-中一-·-考试与面试" tabindex="-1">启思中学 · 年份未注明 · 中一 · 考试与面试 <a class="header-anchor" href="#启思中学-·-年份未注明-·-中一-·-考试与面试" aria-label="Permalink to &quot;启思中学 · 年份未注明 · 中一 · 考试与面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/creative-secondary">← 返回启思中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-css-s1-jan-interactive" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-jan-interactive" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-jan-interactive}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 1月</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>语文：</strong> 中文（口语未注明）</p><p><strong>个人及阅读问答</strong></p><p>个人问答、白话文阅读理解与古诗分析。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>朗读与个人问题</strong></p><p>朗读文章后回答问题；个人问题围绕家庭与生活城市，也会追问“你数学好，是因为天赋还是其他原因？”家长认为问题因人而异，难度不高。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>平板答题</strong></p><p>使用iPad答题，时间为10分钟。</p></blockquote><h2 id="record-css-s1-june-interactive" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-june-interactive" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-june-interactive}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 6月</p><h3 id="轮次未注明-·-请以当次考试通知为准-1" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-1" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>申请与评估</strong></p><p>网上申请时提交学生自我介绍视频；获邀后参加中文、英文与数学评估。该场以计算机答题和师生问答进行，没有另设集中纸笔考试。</p></blockquote><blockquote><p><strong>数学：</strong> 英语，附中文标注</p><p><strong>计算机答题</strong></p><p>以计算机完成英文数学题，题目附中文标注。考生认为内容较简单。</p></blockquote><blockquote><p><strong>语文：</strong> 中文，繁体字</p><p><strong>阅读与文言理解</strong></p><p>阅读繁体中文文章；文言文部分需解释文意。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>口语交流</strong></p><p>包含口语提问、对话与追问。家长认为交流内容有一定深度。</p></blockquote><blockquote><p><strong>家长面谈：</strong> 语言未注明</p><p><strong>教育理念</strong></p><p>老师与家长交流学校教育理念、毕业生发展，以及如何让学生从生活与学习中建立联系、培养独立思考和解决问题的能力。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>学校印象</strong></p><p>学生对教学资源和科技体验印象较好，特别提到食品科学；家长认为交流体验愉快。</p></blockquote><h2 id="record-css-s1-may-waiting" tabindex="-1">资料来源：启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css-s1-may-waiting" aria-label="Permalink to &quot;资料来源：启思中学中一春季及秋季入学考经 .pdf {#record-css-s1-may-waiting}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生／家长反馈整理</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 5月</p><h3 id="轮次未注明-·-请以当次考试通知为准-2" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-2" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>评估形式</strong></p><p>以平板答题配合老师问答进行。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读问答</strong></p><p>阅读一篇文章后，回答老师提出的问题。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>学科难度</strong></p><p>考生认为数学与语文较简单。</p><p><strong>候补结果</strong></p><p>考后获得候补资格。家长向学校查询时获告知处于候补名单中段，其后于7月16日收到正式录取通知。</p></blockquote><h2 id="record-css002" tabindex="-1">资料来源：启思中学七年级插班.png；启思中学中一春季及秋季入学考经 .pdf <a class="header-anchor" href="#record-css002" aria-label="Permalink to &quot;资料来源：启思中学七年级插班.png；启思中学中一春季及秋季入学考经 .pdf {#record-css002}&quot;">​</a></h2><p><strong>资料类型：</strong> 考生反馈</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><p><strong>反馈时间：</strong> 11月</p><h3 id="轮次未注明-·-请以当次考试通知为准-3" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准-3" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>考点范围</strong></p><p>题目涉及三角形面积、体积、最小公倍数及最大公因数。</p></blockquote><blockquote><p><strong>中文：</strong> 中文（口语语种未注明）</p><p><strong>文章阅读</strong></p><p>先阅读较长的文章，再回答教师提出的几个问题。</p><p><strong>古诗理解与应用</strong></p><p>随后阅读《悯农》，说明诗中表达的思想感情，并回答若将诗张贴在学校，应选择哪个位置。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>自我介绍与阅读</strong></p><p>先作自我介绍，再阅读一篇关于水的文章，回答教师的问题。</p><p><strong>向教师提问</strong></p><p>最后由考生向教师提出与学校有关的问题。</p></blockquote>',42)])])}const h=t(n,[["render",p]]);export{u as __pageData,h as default};
